-- MySQL schema for Event Scheduler. Run with: npm run db:setup
-- Ids are UUIDs generated by the app (crypto.randomUUID).

CREATE TABLE IF NOT EXISTS users (
  userId     CHAR(36)     PRIMARY KEY,
  firstName  VARCHAR(50)  NOT NULL,
  email      VARCHAR(100) NOT NULL UNIQUE,
  password   VARCHAR(100) NOT NULL,
  createdAt  DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updatedAt  DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  isArchived BOOLEAN      NOT NULL DEFAULT FALSE
);

CREATE TABLE IF NOT EXISTS events (
  eventId       CHAR(36)     PRIMARY KEY,
  title         VARCHAR(255) NOT NULL,
  description   TEXT,
  startDateTime DATETIME     NOT NULL,
  endDateTime   DATETIME     NOT NULL,
  createdBy     CHAR(36)     NOT NULL,
  createdAt     DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  -- Set automatically every time the event is edited
  updatedAt     DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  -- Deleting an event only fills this in (soft delete); NULL means the event is live
  deletedAt     DATETIME,
  isArchived    BOOLEAN      NOT NULL DEFAULT FALSE,
  KEY idx_events_creator (createdBy, deletedAt),
  FOREIGN KEY (createdBy) REFERENCES users(userId),
  CHECK (startDateTime <= endDateTime)
);

CREATE TABLE IF NOT EXISTS participants (
  eventId CHAR(36) NOT NULL,
  userId  CHAR(36) NOT NULL,
  PRIMARY KEY (eventId, userId),
  KEY idx_participants_user (userId),
  FOREIGN KEY (eventId) REFERENCES events(eventId),
  FOREIGN KEY (userId)  REFERENCES users(userId)
);
